package api

import (
	"net/http"
	"testing"
)

func TestHeimdallTwoPartialRefundsCannotExceedThePayment(t *testing.T) {
	h := newRefundRoutes()
	pay := newPayment(t, h, "m-1", 100)
	body := `{"payment_id": "` + pay + `", "amount": 60}`
	if rec := send(t, h, http.MethodPost, "/refunds", "m-1", "k1", body); rec.Code != http.StatusCreated {
		t.Fatalf("first refund of 60 = %d: %s", rec.Code, rec.Body)
	}
	if rec := send(t, h, http.MethodPost, "/refunds", "m-1", "k2", body); rec.Code != http.StatusUnprocessableEntity {
		t.Fatalf("second refund of 60 on a payment of 100 = %d, want 422: %s", rec.Code, rec.Body)
	}
}

