package api

import (
	"encoding/json"
	"net/http"
	"testing"
)

func TestHeimdallAnotherMerchantCannotReadARefund(t *testing.T) {
	h := newRefundRoutes()
	pay := newPayment(t, h, "m-1", 100)
	rec := send(t, h, http.MethodPost, "/refunds", "m-1", "k1", `{"payment_id": "`+pay+`", "amount": 10}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("refund = %d: %s", rec.Code, rec.Body)
	}
	var ref struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &ref); err != nil {
		t.Fatal(err)
	}
	if got := send(t, h, http.MethodGet, "/refunds/"+ref.ID, "m-2", "", ""); got.Code != http.StatusNotFound {
		t.Fatalf("GET another merchant's refund = %d, want 404: %s", got.Code, got.Body)
	}
}

